function finalize(){state.nextOperation=result.operation;return result;}
let extractedIntent = $context.$nodes.XDX_INTERPRET_SUPPLIER_REQUEST.$output;
const selectedDetail = /^\s*(?:show|get|view)\s+(?:the\s+)?details\s+(?:for|of)\s+the\s+selected\s+(site|contact|address)\s*[.!?]?\s*$/i.exec($context.$system.$inputMessage||'');
const explicitChildDetail = /^\s*(?:show|get|view)\s+(site|contact|address)\s+details\s+for\s+\1\s+ID\s+([1-9][0-9]{0,17})\s+for\s+supplier\s+(number|ID)\s+([1-9][0-9]{0,17})\s*[.!?]?\s*$/i.exec($context.$system.$inputMessage||'');
let intent = selectedDetail ? {intent:'children',resource:{site:'sites',contact:'contacts',address:'addresses'}[selectedDetail[1].toLowerCase()],matchMode:'selection',term:'',childMode:'selection',childTerm:'',includeInactive:false} : explicitChildDetail ? {intent:'children',resource:{site:'sites',contact:'contacts',address:'addresses'}[explicitChildDetail[1].toLowerCase()],matchMode:explicitChildDetail[3].toLowerCase()==='number'?'number':'id',term:explicitChildDetail[4],childMode:'id',childTerm:explicitChildDetail[2],includeInactive:false} : extractedIntent;
const state = JSON.parse(JSON.stringify($context.$variables.supplierState));
const result = {operation:'display',state:state};
state.response={message:'Describe the supplier you want to find, or the change to your current draft.'};
function stop(message){state.response={message:message};return finalize();}
function literal(value){return "'"+value.replace(/'/g,"''")+"'";}
function key(value){return (typeof value==='string' && /^[1-9][0-9]{0,17}$/.test(value)) || (typeof value==='number' && value>0 && value<=9007199254740991 && Math.floor(value)===value);}
const actions=['search','detail','template','edit','choices','children','site_template','child_create','next','unsupported'];
const activeChild=state.draft&&['address','contact'].indexOf(state.draft.kind)>=0?state.draft:null;
 const raw=$context.$system.$inputMessage||'',fieldEdit=/^\s*(?:change|set)\s+(AddressName|CountryCode|AddressLine1|City|State|PostalCode|Email|FirstName|LastName)\s+to\s+([\s\S]+?)\s*$/i.exec(raw)||/^\s*(AddressName|CountryCode|AddressLine1|City|State|PostalCode|Email|FirstName|LastName)\s*:\s*([\s\S]+?)\s*$/i.exec(raw);
 if(activeChild&&(fieldEdit||intent&&intent.intent==='edit')){
  const d=activeChild,fields=d.kind==='address'?['AddressName','CountryCode','AddressLine1','City','State','PostalCode','Email']:['FirstName','LastName','Email'];
  if(['editing','reviewed'].indexOf(d.status)<0||state.attempts.some(function(a){return a.requestId===d.requestId;}))return stop('This child request cannot be edited after an attempt.');
  let patch={};if(fieldEdit){const f=fields.filter(function(f){return f.toLowerCase()===fieldEdit[1].toLowerCase();})[0];if(!f)return stop('That field does not belong to the active '+d.kind+' draft.');patch[f]=fieldEdit[2];}else{patch=intent.childPatch;if(!patch||typeof patch!=='object'||Array.isArray(patch)||Object.keys(patch).some(function(f){return fields.indexOf(f)<0&&patch[f]!==null;}))return stop('Supply only required fields for the active '+d.kind+' draft.');}
  const changes=Object.keys(patch).filter(function(f){return patch[f]!==null;});if(!changes.length||changes.some(function(f){return typeof patch[f]!=='string'||!patch[f].trim();}))return stop('Specify the required draft field and its replacement value.');
  if(!Number.isSafeInteger(d.revision)||d.revision>=9007199254740991)return stop('Cancel this draft before starting a new revision.');changes.forEach(function(f){d.payload[f]=patch[f];});d.revision++;d.status='editing';delete d.reviewedRevision;delete d.fieldsVerifiedRevision;delete d.duplicateCheckedRevision;delete state.childConfirmation;result.operation='child_validate';return finalize();
 }
if(!intent || actions.indexOf(intent.intent)<0 || typeof intent.includeInactive!=='boolean')return stop('Please describe the supplier search or draft change.');
if(intent.intent==='unsupported')return finalize();
function lookup(purpose){const date=$context.$system.$currentDate;if(typeof date!=='string' || !/^\d{4}-\d{2}-\d{2}$/.test(date))return stop('The current business date is unavailable. Your draft is retained.');state.pending={purpose:purpose,activeDate:date,limit:100,offset:0};if(purpose==='classifications'){state.pending.requestId=state.draft.requestId;state.pending.revision=state.draft.revision;}result.operation='classifications';return finalize();}
if(intent.intent==='choices')return lookup('choices');
if(intent.intent==='edit'&&state.draft&&state.draft.kind==='site'){
 const draft=state.draft;if(['editing','reviewed'].indexOf(draft.status)<0||state.attempts.some(function(a){return a.requestId===draft.requestId;}))return stop('This site request cannot be edited after an attempt.');
 const patch=intent.patch;if(!patch||typeof patch!=='object'||Array.isArray(patch)||Object.keys(patch).some(function(k){return k!=='SupplierSite'&&patch[k]!==null;}))return stop('Change the new site name; the source address, procurement BU and reviewed assignment pairs remain attached to this source.');
 const name=patch.SupplierSite;if(typeof name!=='string'||!name.trim()||name.length>240||/[\x00-\x1f]/.test(name))return stop('Provide a new site name of up to 240 characters.');
 if(!Number.isSafeInteger(draft.revision)||draft.revision>=9007199254740991)return stop('Cancel this draft and start again; its revision cannot advance.');
 draft.payload.SupplierSite=name;draft.revision++;draft.status='editing';delete draft.reviewedRevision;delete draft.duplicateCheckedRevision;delete state.siteConfirmation;
 state.sitePreparation={suppliers_Id:String(draft.supplier.SupplierId),supplier:draft.supplier,source:draft.source,address:draft.address,newName:name,assignmentsComplete:draft.assignmentsComplete,editingRequestId:draft.requestId,editingRevision:draft.revision};
 result.operation='site_name_check';return finalize();
}
if(intent.intent==='edit'){
 const draft=state.draft;
 if(!draft || ['editing','reviewed'].indexOf(draft.status)<0 || state.attempts.some(function(a){return a.requestId===draft.requestId;}))return stop('There is no editable supplier draft. Start by choosing a supplier template.');
 const patch=intent.patch,fields=['Supplier','SupplierType','BusinessRelationship','TaxOrganizationType'];
 if(!patch || typeof patch!=='object' || Array.isArray(patch) || Object.keys(patch).some(function(k){return fields.indexOf(k)<0 && !(k==='SupplierSite' && patch[k]===null);}))return stop('Only the new supplier name and the three reviewed classifications can be edited.');
 const changes=Object.keys(patch).filter(function(k){return patch[k]!==null;});
 if(!changes.length)return stop('Tell me which draft field to change.');
 if(changes.some(function(k){return typeof patch[k]!=='string' || !patch[k].trim() || patch[k].length>(k==='Supplier'?360:80);}))return stop('Supply a nonempty name of up to 360 characters and classification values of up to 80 characters.');
 if(!Number.isSafeInteger(draft.revision) || draft.revision>=9007199254740991)return stop('The draft revision cannot be advanced. Cancel this draft and start again.');
 const classificationsUnchanged=changes.every(function(k){return k==='Supplier' || patch[k]===draft.payload[k];});const wasVerified=draft.classificationsVerified===true;
 changes.forEach(function(k){draft.payload[k]=patch[k];});draft.revision+=1;draft.status='editing';delete draft.reviewedRevision;delete draft.duplicateCheckedRevision;
 draft.classificationsVerified=(wasVerified && classificationsUnchanged) || ['SupplierType','BusinessRelationship','TaxOrganizationType'].every(function(k){return draft.payload[k]===draft.source[k];});
 state.response={message:'Draft updated. Review the new revision before confirming.',requestId:draft.requestId,revision:draft.revision,payload:draft.payload};
 if(!draft.classificationsVerified)return lookup('classifications');
 if(!draft.payload.Supplier || !draft.payload.Supplier.trim())return stop('Classifications updated. What name should the new supplier have?');
 state.pending={purpose:'duplicate',q:'Supplier='+literal(draft.payload.Supplier),limit:1,offset:0,requestId:draft.requestId,revision:draft.revision,name:draft.payload.Supplier};result.operation='duplicate';return finalize();
}
if(intent.intent==='next' && ['sites','contacts','addresses'].indexOf(state.activeRead)>=0){state.pending={purpose:'children',childRequest:{resource:state.activeRead,childMode:'next',childTerm:''}};result.operation='children';return finalize();}
if(intent.intent==='next'){
 const search=state.search;
 if(!search || search.hasMore!==true || !Number.isSafeInteger(search.nextOffset) || search.nextOffset<0 || typeof search.q!=='string' || !Number.isSafeInteger(search.limit) || search.limit<1 || search.limit>25)return stop('There is no next supplier page to retrieve.');
 state.pending={purpose:'search',q:search.q,limit:search.limit,offset:search.nextOffset,includeInactive:search.includeInactive===true};result.operation='list';return finalize();
}
if((intent.intent==='template'||intent.intent==='site_template'||intent.intent==='child_create') && state.draft)return stop('A draft already exists. Edit it, or cancel its exact request and revision before starting another.');
const selectedTemplateParent=(intent.intent==='template'||intent.intent==='site_template'||intent.intent==='child_create') && /\b(?:based on|from|for)\s+(?:the\s+)?selected supplier\b/i.test($context.$system.$inputMessage||'');
const selectedReference=selectedTemplateParent || intent.intent==='child_create'&&/\bselected (?:supplier|address|contact)\b/i.test($context.$system.$inputMessage||'') || intent.intent==='children' && /\bselected (?:supplier|site|contact|address)\b/i.test($context.$system.$inputMessage||'');
const mode=selectedReference?'selection':intent.matchMode;
const term=typeof intent.term==='string'?intent.term.trim():'';
const newName=typeof intent.newName==='string'?intent.newName:'';
if(newName.length>360)return stop('The new supplier name must be at most 360 characters.');
const pending={purpose:intent.intent,newName:newName,includeInactive:intent.intent==='template' || intent.includeInactive===true && /\binactive\b/i.test($context.$system.$inputMessage||'')};
if(intent.intent==='child_create'){
  if(!/\b(?:create|new|copy|clone|prepare)\b/i.test($context.$system.$inputMessage||''))return stop('An explicit request to prepare a new address or contact is required.');
  const kind=intent.resource==='addresses'?'address':intent.resource==='contacts'?'contact':null,creationMode=intent.creationMode;
  if(!kind||['direct','template'].indexOf(creationMode)<0)return stop('Choose direct-entry or same-supplier template creation for an address or contact.');
  const fields=kind==='address'?['AddressName','CountryCode','AddressLine1','City','State','PostalCode','Email']:['FirstName','LastName','Email'],patch=intent.childPatch||{};
  if(typeof patch!=='object'||Array.isArray(patch)||Object.keys(patch).some(function(f){return fields.indexOf(f)<0&&patch[f]!==null;}))return stop('Supply only the required fields for this child.');
  const clean={};fields.forEach(function(f){if(Object.prototype.hasOwnProperty.call(patch,f)&&patch[f]!==null)clean[f]=patch[f];});if(kind==='address'&&newName)clean.AddressName=newName;
  const selectedSource=/\bselected (?:address|contact)\b/i.test($context.$system.$inputMessage||'');pending.childCreateRequest={kind:kind,mode:creationMode,patch:clean,sourceMode:selectedSource?'selection':intent.childMode,sourceTerm:typeof intent.childTerm==='string'?intent.childTerm:''};
 }
if(intent.intent==='site_template'){
 if(newName.length>240)return stop('The new site name must be at most 240 characters.');
 const sm=intent.childMode||'contains',st=typeof intent.childTerm==='string'?intent.childTerm:'';
 if(['exact','contains','id','selection'].indexOf(sm)<0)return stop('Choose a source site by name, site ID or the selected site.');
 pending.siteRequest={mode:sm,term:st};
}
if(intent.intent==='children'){
 const resource=intent.resource;
 if(['sites','contacts','addresses'].indexOf(resource)<0)return stop('Ask for supplier sites, contacts or addresses.');
 const selectedChild=/\bselected (?:site|contact|address)\b/i.test($context.$system.$inputMessage||'');
 const childMode=selectedChild?'selection':intent.childMode||'all';
 if(['all','exact','contains','id','selection','next'].indexOf(childMode)<0)return stop('Describe which '+resource+' to show.');
 pending.childRequest={resource:resource,childMode:childMode,childTerm:typeof intent.childTerm==='string'?intent.childTerm:'',includeInactive:pending.includeInactive};
 state.pending=pending;
 if(childMode==='next'){result.operation='children';return finalize();}
}
if(mode==='selection'){
 if(!state.selection || !key(state.selection.SupplierId))return stop('Search for and select a supplier first.');
 pending.suppliers_Id=String(state.selection.SupplierId);state.pending=pending;result.operation='get';return finalize();
}
if(mode==='id'){
 if(!key(term))return stop('Supply a valid internal supplier ID, or search by supplier name or displayed supplier number.');
 pending.suppliers_Id=term;state.pending=pending;result.operation='get';return finalize();
}
if(['contains','exact','number'].indexOf(mode)<0 || !term || term.length>360 || /[\x00-\x1f]/.test(term))return stop('Supply a supplier name or displayed supplier number to search.');
if(mode==='contains' && /[%_\\]/.test(term))return stop('For this name, use an exact supplier-name search or the displayed supplier number.');
let q=mode==='number'?'SupplierNumber='+literal(term):mode==='exact'?'Supplier='+literal(term):'Supplier like '+literal('%'+term+'%');
if(!pending.includeInactive){const date=$context.$system.$currentDate;if(typeof date!=='string' || !/^\d{4}-\d{2}-\d{2}$/.test(date))return stop('The current business date is unavailable. The supplier search was not run.');q+=" and (InactiveDate is null or InactiveDate > '"+date+"')";}
pending.q=q;pending.limit=25;pending.offset=0;state.pending=pending;result.operation='list';return finalize();
